('reading', '{"text": "Many employees were surprised to learn that the company planned to relocate its headquarters next year."}', 0.61, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('reading', '{"text": "The professor explained that the experiment''s results contradicted much of the earlier research."}', 0.62, 'B2', 'approved', 'manual', 'education', 'practice', :'s2_id', 3),
('reading', '{"text": "Although demand has grown steadily, the company has been reluctant to expand its production capacity."}', 0.60, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('reading', '{"text": "She was hesitant to accept the promotion because it would require relocating to another country."}', 0.62, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('reading', '{"text": "The budget committee ultimately rejected the proposal, citing concerns about its feasibility."}', 0.65, 'B2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('reading', '{"text": "Critics argue that the new policy fails to address the underlying causes of the problem."}', 0.66, 'B2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('reading', '{"text": "Despite years of planning, the construction project encountered unexpected regulatory obstacles."}', 0.67, 'B2', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('reading', '{"text": "The researchers acknowledged that their findings, while promising, required further validation."}', 0.65, 'B2', 'approved', 'manual', 'education', 'practice', :'s3_id', 4),
