INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('reading_selective', '{"text": "Due to unexpected demand, the conference has been moved to a larger venue across town.", "question": "Why was the conference moved?"}', 0.55, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["unexpected demand", "because of demand"]}', :'s1_id', 1),
('reading_selective', '{"text": "The contract will automatically renew unless either party gives written notice thirty days in advance.", "question": "How much notice is required to cancel?"}', 0.57, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["thirty days", "30 days"]}', :'s1_id', 2),
('reading_selective', '{"text": "The warranty covers manufacturing defects but does not include damage caused by improper use.", "question": "What does the warranty not cover?"}', 0.58, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["damage from improper use", "improper use"]}', :'s1_id', 3),
('reading_selective', '{"text": "Applicants must submit their portfolios by Friday to be considered for the spring intake.", "question": "What is the deadline?"}', 0.56, 'B2', 'approved', 'manual', 'education', 'practice', '{"acceptable_answers": ["friday"]}', :'s1_id', 4),
('reading_selective', '{"text": "The survey revealed that most employees preferred flexible hours over a higher salary.", "question": "What did most employees prefer?"}', 0.57, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["flexible hours"]}', :'s1_id', 5),
('reading_selective', '{"text": "Although the flight was delayed by two hours, passengers were offered meal vouchers as compensation.", "question": "What were passengers offered?"}', 0.60, 'B2', 'approved', 'manual', 'travel', 'practice', '{"acceptable_answers": ["meal vouchers"]}', :'s2_id', 1),
('reading_selective', '{"text": "The museum''s new exhibit focuses on sustainable architecture from the past two decades.", "question": "What does the exhibit focus on?"}', 0.61, 'B2', 'approved', 'manual', 'culture', 'practice', '{"acceptable_answers": ["sustainable architecture"]}', :'s2_id', 2),
('reading_selective', '{"text": "The company reported a slight decline in revenue, attributing it to rising material costs.", "question": "What caused the revenue decline?"}', 0.62, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["rising material costs", "material costs"]}', :'s2_id', 3),
('reading_selective', '{"text": "Residents were asked to conserve water after the reservoir levels dropped below normal.", "question": "Why were residents asked to conserve water?"}', 0.60, 'B2', 'approved', 'manual', 'community', 'practice', '{"acceptable_answers": ["low reservoir levels", "reservoir levels dropped"]}', :'s2_id', 4),
('reading_selective', '{"text": "The new software update improves battery life but removes an older, rarely used feature.", "question": "What does the update improve?"}', 0.62, 'B2', 'approved', 'manual', 'technology', 'practice', '{"acceptable_answers": ["battery life"]}', :'s2_id', 5),
('reading_selective', '{"text": "Despite initial resistance, most staff eventually adapted well to the new scheduling system.", "question": "How did staff eventually respond?"}', 0.65, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["adapted well", "they adapted"]}', :'s3_id', 1),
('reading_selective', '{"text": "The city plans to plant two thousand trees over the next five years as part of a green initiative.", "question": "How many trees will be planted?"}', 0.66, 'B2', 'approved', 'manual', 'environment', 'practice', '{"acceptable_answers": ["two thousand", "2000"]}', :'s3_id', 2),
('reading_selective', '{"text": "The report concluded that remote work had little measurable effect on overall productivity.", "question": "What did the report conclude?"}', 0.67, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["little effect on productivity", "no real effect"]}', :'s3_id', 3),
('reading_selective', '{"text": "The airline announced it would add three new routes beginning next spring.", "question": "How many new routes were announced?"}', 0.65, 'B2', 'approved', 'manual', 'travel', 'practice', '{"acceptable_answers": ["three", "3"]}', :'s3_id', 4),
('reading_selective', '{"text": "Volunteers collected over five hundred kilograms of litter during the weekend cleanup event.", "question": "How much litter was collected?"}', 0.68, 'B2', 'approved', 'manual', 'environment', 'practice', '{"acceptable_answers": ["five hundred kilograms", "500 kilograms", "500 kg"]}', :'s3_id', 5);
