INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('conversations', '{"dialogue": "A: The client pushed back the deadline. B: That''s a relief. A: Yes, it gives us two more weeks.", "question": "How much extra time do they have?"}', 0.55, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["two more weeks", "2 weeks"]}', :'s1_id', 1),
