('conversations', '{"dialogue": "A: Our main competitor just lowered their prices. B: By how much? A: About fifteen percent.", "question": "By how much did the competitor lower prices?"}', 0.57, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["fifteen percent", "15 percent", "15%"]}', :'s1_id', 3),
