('conversations', '{"dialogue": "A: I heard the merger fell through. B: Really? What happened? A: The two sides couldn''t agree on valuation.", "question": "Why did the merger fall through?"}', 0.58, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["disagreement over valuation", "they could not agree on valuation"]}', :'s1_id', 5),
('conversations', '{"dialogue": "A: The survey results came back. B: And? A: Customer satisfaction dropped slightly this quarter.", "question": "What happened to customer satisfaction?"}', 0.60, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["it dropped slightly", "dropped"]}', :'s2_id', 1),
('conversations', '{"dialogue": "A: We''re over capacity at the warehouse. B: Since when? A: Since the new product line launched.", "question": "Since when has the warehouse been over capacity?"}', 0.61, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["since the new product line launched", "since the launch"]}', :'s2_id', 2),
('conversations', '{"dialogue": "A: The regulator flagged our report. B: For what reason? A: A few figures didn''t match last quarter''s filing.", "question": "Why was the report flagged?"}', 0.62, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["figures did not match", "mismatched figures"]}', :'s2_id', 3),
('conversations', '{"dialogue": "A: Did the new hire start yet? B: Yes, last Monday. A: How''s it going so far?", "question": "When did the new hire start?"}', 0.60, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["last Monday", "Monday"]}', :'s2_id', 4),
('conversations', '{"dialogue": "A: We lost the Henderson account. B: That''s a big loss. A: Yes, it was almost a third of our revenue.", "question": "How much of their revenue did the account represent?"}', 0.62, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["almost a third", "about one third"]}', :'s2_id', 5),
('conversations', '{"dialogue": "A: The acquisition talks stalled. B: Over what? A: Mostly disagreements about leadership roles.", "question": "What caused the talks to stall?"}', 0.65, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["disagreements about leadership roles", "leadership disagreements"]}', :'s3_id', 1),
('conversations', '{"dialogue": "A: The factory passed the inspection. B: With any issues? A: Just a couple of minor recommendations.", "question": "What did the inspection find?"}', 0.66, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["minor recommendations", "a couple of minor issues"]}', :'s3_id', 2),
('conversations', '{"dialogue": "A: The client wants a full refund. B: Did we agree? A: Only a partial one, after negotiation.", "question": "What was finally agreed?"}', 0.67, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["a partial refund", "partial refund"]}', :'s3_id', 3),
('conversations', '{"dialogue": "A: Our forecast missed by a wide margin. B: How wide? A: Almost twenty percent under projections.", "question": "By how much did the forecast miss?"}', 0.65, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["almost twenty percent", "20 percent", "20%"]}', :'s3_id', 4),
('conversations', '{"dialogue": "A: The policy change caused backlash. B: From whom? A: Mainly from long-term customers.", "question": "Who reacted most to the policy change?"}', 0.68, 'B2', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["long-term customers", "long term customers"]}', :'s3_id', 5);
