INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('story_retelling', '{"story": "After months of declining sales, a small bookstore owner decided to host weekly author events. Attendance grew steadily, and the events eventually brought in enough new customers to reverse the decline."}', 0.55, 'B2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('story_retelling', '{"story": "A young engineer proposed an unconventional fix for a recurring equipment failure. Senior staff were skeptical at first, but after testing, the fix worked and became standard practice."}', 0.56, 'B2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('story_retelling', '{"story": "A city struggled with overcrowded buses during rush hour. Officials introduced a staggered work-hour policy for government employees, which noticeably eased congestion."}', 0.57, 'B2', 'approved', 'manual', 'community', 'practice', :'s1_id', 3),
('story_retelling', '{"story": "A restaurant chain faced criticism for inconsistent food quality across locations. They retrained all kitchen staff using a standardized recipe guide, and complaints dropped significantly."}', 0.56, 'B2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('story_retelling', '{"story": "A university professor noticed students struggling with a difficult textbook. She created simplified supplementary notes, and test scores improved across the class."}', 0.58, 'B2', 'approved', 'manual', 'education', 'practice', :'s1_id', 5),
('story_retelling', '{"story": "A startup''s first product failed to gain traction. The founders pivoted to a different market segment based on user feedback, and the company eventually became profitable."}', 0.60, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('story_retelling', '{"story": "A factory experienced frequent safety violations despite repeated warnings. Management introduced mandatory safety briefings before every shift, and violations decreased substantially."}', 0.61, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('story_retelling', '{"story": "A hospital''s emergency room faced long patient wait times. Staff redesigned the intake process to triage patients more efficiently, cutting average wait times nearly in half."}', 0.62, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('story_retelling', '{"story": "A software company struggled with a high number of support tickets about the same issue. They created a detailed help article addressing it directly, and ticket volume dropped sharply."}', 0.60, 'B2', 'approved', 'manual', 'technology', 'practice', :'s2_id', 4),
('story_retelling', '{"story": "A charity noticed donor engagement declining over several years. They began sharing detailed impact reports showing exactly how funds were used, which renewed donor confidence."}', 0.62, 'B2', 'approved', 'manual', 'community', 'practice', :'s2_id', 5),
('story_retelling', '{"story": "A manufacturing firm discovered a competitor was undercutting its prices significantly. Rather than matching the price, they emphasized product quality and customer service in their marketing, retaining most loyal customers."}', 0.65, 'B2', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('story_retelling', '{"story": "An airline faced backlash after a widely publicized service failure. The CEO personally addressed the issue publicly and offered compensation, which helped restore some public trust."}', 0.66, 'B2', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('story_retelling', '{"story": "A research team''s initial hypothesis was disproven by their own data. Rather than discarding the project, they pursued the unexpected finding, which led to a more significant discovery."}', 0.67, 'B2', 'approved', 'manual', 'education', 'practice', :'s3_id', 3),
('story_retelling', '{"story": "A retailer noticed that a popular product was frequently out of stock. They renegotiated terms with their supplier to secure priority shipments, resolving the shortage within a month."}', 0.65, 'B2', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('story_retelling', '{"story": "A city government faced pushback over a proposed tax increase. After hosting several public forums to explain the reasoning, opposition softened and the measure eventually passed."}', 0.68, 'B2', 'approved', 'manual', 'community', 'practice', :'s3_id', 5);
