INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('summary_and_opinion', '{"passage": "More schools are introducing coding classes at an early age. Supporters say it builds valuable problem-solving skills, while critics argue it takes time away from other important subjects."}', 0.55, 'B2', 'approved', 'manual', 'education', 'practice', '{"key_points": ["schools introduce early coding classes", "supporters cite problem-solving skills", "critics worry about time away from other subjects"]}', :'s1_id', 1),
('summary_and_opinion', '{"passage": "Many cities are banning single-use plastic bags. Environmentalists praise the move, while some small business owners worry about the added cost of alternatives."}', 0.56, 'B2', 'approved', 'manual', 'environment', 'practice', '{"key_points": ["cities ban single-use plastic bags", "environmentalists praise it", "business owners worry about costs"]}', :'s1_id', 2),
('summary_and_opinion', '{"passage": "Companies are increasingly monitoring employee productivity through software. Supporters say it improves accountability, but critics argue it damages trust and morale."}', 0.57, 'B2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["companies monitor productivity with software", "supporters cite accountability", "critics say it damages trust"]}', :'s1_id', 3),
('summary_and_opinion', '{"passage": "Some airlines now charge extra for carry-on luggage. The airlines say it keeps base fares lower, but passengers often feel misled by the final total cost."}', 0.56, 'B2', 'approved', 'manual', 'travel', 'practice', '{"key_points": ["airlines charge extra for carry-on", "airlines say it lowers base fares", "passengers feel misled by final cost"]}', :'s1_id', 4),
('summary_and_opinion', '{"passage": "Universities are expanding online degree programs. Proponents highlight flexibility and lower costs, while skeptics question whether online learning matches in-person quality."}', 0.58, 'B2', 'approved', 'manual', 'education', 'practice', '{"key_points": ["universities expand online degrees", "proponents cite flexibility and cost", "skeptics question quality"]}', :'s1_id', 5),
('summary_and_opinion', '{"passage": "A growing number of retailers are removing self-checkout machines after rising theft. Some customers appreciate faster service with cashiers, while others preferred the convenience of self-checkout."}', 0.60, 'B2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["retailers remove self-checkout machines", "theft was rising", "some miss the convenience"]}', :'s2_id', 1),
('summary_and_opinion', '{"passage": "Several governments are considering a four-day work week trial. Advocates cite improved wellbeing, while opponents worry about reduced output in certain industries."}', 0.61, 'B2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["governments consider four-day work week trials", "advocates cite wellbeing", "opponents worry about output"]}', :'s2_id', 2),
('summary_and_opinion', '{"passage": "More restaurants are adding mandatory service charges instead of relying on tips. Supporters say it creates fairer pay, while some customers feel it removes their choice."}', 0.62, 'B2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["restaurants add mandatory service charges", "supporters cite fairer pay", "customers feel it removes choice"]}', :'s2_id', 3),
('summary_and_opinion', '{"passage": "Public libraries are increasingly offering digital services like e-books and streaming. Fans say it modernizes the library, while others feel it strays from the library''s traditional purpose."}', 0.60, 'B2', 'approved', 'manual', 'culture', 'practice', '{"key_points": ["libraries offer more digital services", "fans say it modernizes libraries", "others feel it strays from tradition"]}', :'s2_id', 4),
('summary_and_opinion', '{"passage": "Some companies are requiring employees to return to the office full-time. Supporters argue it strengthens collaboration, while employees often cite the loss of flexibility."}', 0.62, 'B2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["companies require full return to office", "supporters cite collaboration", "employees cite lost flexibility"]}', :'s2_id', 5),
('summary_and_opinion', '{"passage": "Several cities have introduced congestion pricing for vehicles entering downtown areas. Officials say it reduces traffic and funds public transit, while drivers often view it as an unfair extra cost."}', 0.65, 'B2', 'approved', 'manual', 'community', 'practice', '{"key_points": ["cities introduce congestion pricing", "officials cite reduced traffic and transit funding", "drivers see it as unfair"]}', :'s3_id', 1),
('summary_and_opinion', '{"passage": "A growing number of employers are using AI tools to screen job applications. Supporters say it saves time, while critics worry qualified candidates may be unfairly filtered out."}', 0.66, 'B2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["employers use AI to screen applications", "supporters cite time savings", "critics worry about unfair filtering"]}', :'s3_id', 2),
('summary_and_opinion', '{"passage": "Some national parks are now limiting daily visitor numbers. Conservationists support the limits to protect ecosystems, while tourism businesses worry about lost revenue."}', 0.67, 'B2', 'approved', 'manual', 'environment', 'practice', '{"key_points": ["parks limit daily visitors", "conservationists support protecting ecosystems", "tourism businesses worry about revenue"]}', :'s3_id', 3),
('summary_and_opinion', '{"passage": "Several banks are closing physical branches in favor of online banking. Supporters cite lower costs, while elderly and rural customers often struggle with the shift."}', 0.65, 'B2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["banks close branches for online banking", "supporters cite lower costs", "elderly and rural customers struggle"]}', :'s3_id', 4),
('summary_and_opinion', '{"passage": "Many companies now require job candidates to complete timed skills tests before interviews. Supporters say it ensures fairness, while critics argue it adds unnecessary pressure and favors test-takers over practical experience."}', 0.68, 'B2', 'approved', 'manual', 'business', 'practice', '{"key_points": ["companies require timed skills tests", "supporters say it ensures fairness", "critics say it favors test-takers over experience"]}', :'s3_id', 5);
