('typing', '{"text": "Despite the challenges of managing a distributed team, many companies have found that clear communication tools make remote collaboration surprisingly effective."}', 0.55, 'B2', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('typing', '{"text": "The committee reviewed dozens of proposals before narrowing the list down to three finalists for further consideration."}', 0.56, 'B2', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('typing', '{"text": "Although the initial rollout faced technical issues, the updated system now processes transactions far more reliably."}', 0.57, 'B2', 'approved', 'manual', 'technology', 'practice', :'s1_id', 3),
('typing', '{"text": "Customer feedback suggested that the checkout process was too complicated, prompting the team to simplify it significantly."}', 0.56, 'B2', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('typing', '{"text": "The city''s new recycling program has reduced landfill waste considerably over the past twelve months."}', 0.58, 'B2', 'approved', 'manual', 'environment', 'practice', :'s1_id', 5),
('typing', '{"text": "The negotiation team spent several weeks drafting terms that both sides could agree on without further delays."}', 0.60, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('typing', '{"text": "Analysts believe the recent price increase reflects rising production costs rather than reduced competition in the market."}', 0.61, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('typing', '{"text": "The hospital introduced a new scheduling system that reduced patient wait times by nearly half."}', 0.60, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('typing', '{"text": "Employees were encouraged to share feedback anonymously, which led to several unexpected and useful suggestions."}', 0.62, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('typing', '{"text": "The startup struggled initially, but a well-timed partnership helped it gain traction in a crowded market."}', 0.61, 'B2', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('typing', '{"text": "While automation has eliminated some roles, it has also created new positions requiring different, often more specialized skills."}', 0.65, 'B2', 'approved', 'manual', 'technology', 'practice', :'s3_id', 1),
